"""Inputs for build_table.py (run rl-compute-share). One dict per model or run.

Observed values cite ledger claim ids (`claims`); everything in `assumptions` is mine. Ranges are (low, high) and the
low / high RL estimates use every low / every high value together. Kinds:
  computed  RL FLOPs from stages (steps x prompts x group x tokens) or a stated token total
  hw        RL FLOPs from GPU-hours x dense peak FLOP/s x an MFU range (no step counts available)
  gpuh      ratio of RL GPU-hours to pretraining GPU-hours (same GPU type), not FLOPs
  stated    a ratio the source states
  nc        not computable from primary sources
Verdict classes (for the figure): elicit, create, mixed, none.
Peak dense BF16 FLOP/s: A100 / A800 312e12 [H-a100-bf16]; H100 / H800 / H200 989.5e12 [H-h100-bf16, H-h100-sparsity,
H-h200-bf16] (H800 assumed equal to H100 SXM in compute; not verified). MFU range for hw rows: 3-30 % (R1-Zero's
token-based estimate implies 3-13 % of peak on its disclosed H800-hours; see REVIEW.md).
"""
A100, H100 = 312e12, 989.5e12
MFU = (0.03, 0.30)
Q25_D = 18e12              # Qwen2.5 pretraining tokens [A-Q25-tokens]
QMATH_D = 19e12            # + Qwen Math Corpus v2 (>1T; corpus size, trained tokens not stated) [A-QMATH-corpus-v2]
Q25_CL = ['A-Q25-tokens']
QMATH_CL = ['A-Q25-tokens', 'A-QMATH-corpus-v2', 'A-QMATH-params']
QWEN_CONTAM = 'Qwen2.5 pretraining includes synthetic math/code data from Qwen2-72B-Instruct and Qwen2-Math-72B-Instruct (A-Q25-synth)'
QMATH_CONTAM = 'Qwen2.5-Math corpus includes data synthesised by Qwen2-Math-72B-Instruct (A-QMATH-synth)'
R1D_CONTAM = 'distilled base: SFT on ~800k DeepSeek-R1 samples (an RL-trained teacher) (C-BASE-r1d_800k, C-BASE-r1d_distilled)'


def S(steps, prompts, group, length, oversample=(1, 1)):
    t = lambda x: x if isinstance(x, tuple) else (x, x)
    return dict(steps=t(steps), prompts=t(prompts), group=t(group), len=t(length), oversample=t(oversample))


